import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "extraction completes in the background for an insurance certificate",
    { tag: "@DOC-02" },
    async ({ apiAs }) => {
      // Background: signed in as member, a vendor in status "draft"
      const member = await apiAs("member");
      const name = uniqueName("DOC-02 Vendor");
      const createResponse = await member.post("/api/vendors", {
        data: {
          name,
          category: "services",
          contact_email: "doc02@example.com",
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      expect(vendor.status).toBe("draft");

      // Given I uploaded "insurance_certificate.txt" as kind "insurance_certificate"
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance_certificate.txt",
            mimeType: "text/plain",
            buffer: fs.readFileSync(sample("insurance_certificate.txt")),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();
      expect(document.vendor_id).toBe(vendor.id);
      expect(document.kind).toBe("insurance_certificate");

      // When processing finishes / Then the document status is "extracted"
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${document.id}`);
            expect(res.status()).toBe(200);
            return (await res.json()).status;
          },
          { timeout: 30_000, intervals: [250, 500, 1000] },
        )
        .toBe("extracted");

      // And the extraction has fields "insurer", "policy_number", "coverage_amount", "expiry_date"
      const extractionResponse = await member.get(`/api/documents/${document.id}/extraction`);
      expect(extractionResponse.status()).toBe(200);
      const extraction = await extractionResponse.json();
      expect(extraction.document_id).toBe(document.id);
      expect(extraction.kind).toBe("insurance_certificate");

      const fields = extraction.fields as Record<string, { value: string | null; confidence: number }>;
      for (const key of ["insurer", "policy_number", "coverage_amount", "expiry_date"]) {
        expect(fields, `field ${key} present`).toHaveProperty(key);
      }

      // And every field has a confidence between 0 and 1
      const entries = Object.entries(fields);
      expect(entries.length).toBeGreaterThan(0);
      for (const [key, field] of entries) {
        expect(typeof field.confidence, `confidence type for ${key}`).toBe("number");
        expect(field.confidence, `confidence for ${key}`).toBeGreaterThanOrEqual(0);
        expect(field.confidence, `confidence for ${key}`).toBeLessThanOrEqual(1);
      }
    },
  );
});
